#include "Ftexact.hpp"

#include <Loop.hpp>
#include <cmath>
#include <complex>
#include <constants_mod.hpp>
#include <scalarselect_mod.hpp>

using namespace constants_mod;
using namespace scalarselect_mod;

std::complex<double> Ftexact(double s23, double mt2) {

  std::complex<double> Ftexact_res, bb1;
  double musq, s;

  //--- musq is irrelevant, set it to some value
  musq = mt2;

  bb1 = loopI2(s23, mt2, mt2, musq, 0);
  if (s23 / mt2 < 0.25) {
    s = s23 / mt2;
    bb1 = std::log(musq / mt2) + s / 6.0 * (1.0 + s / 10.0 * (1.0 + s / 7.0 * (1.0 + s / 6.0)));
  }
  Ftexact_res =
      -(one + six * mt2 * loopI3(s23, 0.0, 0.0, mt2, mt2, mt2, musq, 0)
        + 12.0 * mt2 / s23 * (bb1 - loopI2(0.0, mt2, mt2, musq, 0)));

  // expansion of entire contribution
  if (s23 / mt2 < 0.25) {
    s = s23 / mt2;
    Ftexact_res = s / 20.0 * (1.0 + 2.0 / 21.0 * s * (1.0 + s / 8.0));
  }

  return Ftexact_res;
}

extern "C" {

  std::complex<double> Ftexact_wrapper(double s23, double mt2) {

    std::complex<double> Ftexact_result = Ftexact(s23, mt2);  // @coverage-probe
    return Ftexact_result;
  }

}
